// ---- placements (operation)
async addEntry() {
  this.entMsg = "";
  try {
    const r = await Kav1.post("locations/entries", {
      project: this.nProj, escort_id: this.nEscId || null, escort_name: this.nEscId ? "" : this.nEsc, location_text: this.nLoc,
    });
    this.nEsc = ""; this.nEscId = ""; this.nLoc = ""; await this.refresh(); this.selId = r.id;
  } catch (e) { this.entMsg = e.message; }
},
body(e, patch) {
  return { project: e.project, escort_id: e.escort_id || null, escort_name: e.escort_id ? "" : e.escort_name, location_text: e.location_text, map_id: e.map_id, x: e.x, y: e.y, ...patch };
},
onPick(r) { if (r.escort_id) { const p = this.pool.find(x => x.id === r.escort_id); if (p) { r.escort_phone = p.phone; r.escort_catalog = p.catalog_number; } } },
async saveEntry(e, patch) {

  clearPoint() { if (this.selected) this.saveEntry(this.selected, { map_id: null, x: null, y: null }); },

  // ---- escort pool (operation)
  poolSay(text, err) { this.poolMsg = text; this.poolErr = !!err; },
  async addEscort() {
    try {
      await Kav1.post("locations/escorts", { name: this.pName, catalog_number: this.pCat, phone: this.pPhone });
      this.pName = ""; this.pCat = ""; this.pPhone = ""; this.poolSay("נוסף לפול", false); await this.refresh();
    } catch (e) { this.poolSay(e.message, true); }
  },
  async saveEscort(p) {
    try {
      await Kav1.put("locations/escorts/" + p.id, { name: p.name, catalog_number: p.catalog_number || "", phone: p.phone || "", active: !!p.active });
      this.poolSay("נשמר", false); await this.refresh();
    } catch (e) { this.poolSay(e.message, true); await this.refresh(); }
  },
  async removeEscort(p) {
    if (!confirm("למחוק את " + p.name + " מהפול? מלווה ששויך להצבה יושבת במקום זאת.")) return;
    try {
      const r = await Kav1.del("locations/escorts/" + p.id);
      this.poolSay(r.detail === "deactivated" ? "המלווה משויך להצבות, ולכן הושבת (לא נמחק)" : "נמחק מהפול", false); await this.refresh();
    } catch (e) { this.poolSay(e.message, true); }
  },
};

